package com.daytracker.reading;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

import jakarta.validation.constraints.NotNull;

public final class SessionRequests {

	private SessionRequests() {
	}

	/** The id is generated by the client so a retried create is idempotent. */
	public record Create(@NotNull UUID id, @NotNull UUID bookId, @NotNull LocalDate activityDate,
			@NotNull Integer pagesRead, Integer endingPage, String notes) {
	}

	/**
	 * A partial correction. Only properties present in the JSON are applied, so an
	 * explicit {@code null} ending page (remove the position) differs from an
	 * omitted one. The JSON mapper calls a setter only for present properties.
	 */
	public static class Update {

		private final Set<String> present = new HashSet<>();

		@NotNull
		private Long version;

		private LocalDate activityDate;

		private Integer pagesRead;

		private Integer endingPage;

		private String notes;

		public boolean has(String property) {
			return present.contains(property);
		}

		public Long getVersion() {
			return version;
		}

		public void setVersion(Long version) {
			this.version = version;
		}

		public LocalDate getActivityDate() {
			return activityDate;
		}

		public void setActivityDate(LocalDate activityDate) {
			this.activityDate = activityDate;
			present.add("activityDate");
		}

		public Integer getPagesRead() {
			return pagesRead;
		}

		public void setPagesRead(Integer pagesRead) {
			this.pagesRead = pagesRead;
			present.add("pagesRead");
		}

		public Integer getEndingPage() {
			return endingPage;
		}

		public void setEndingPage(Integer endingPage) {
			this.endingPage = endingPage;
			present.add("endingPage");
		}

		public String getNotes() {
			return notes;
		}

		public void setNotes(String notes) {
			this.notes = notes;
			present.add("notes");
		}

	}

}
